def _cnt(a, b, k):
    s = Fraction(k - b, a)
    if abs(s) > 1:
        return 0
    if abs(s) == 1 or s == 0:
        return 1
    return 2

def skill():
    tot = 0
    for a, b in [(2, 4), (3, 2), (3, 6), (3, 1)]:
        tot += a*b
    return tot

def standard():
    xs = np.linspace(0, 2*math.pi, 200001)[1:-1]
    tot = 0
    for a in range(1, 7):
        for b in range(1, 7):
            n = 0
            for k in (2, 4, 6):
                v = a*np.sin(xs) + b - k
                cross = int((v[:-1]*v[1:] < 0).sum())
                tang = int(((np.abs(v[1:-1]) < 1e-7) & (np.abs(v[1:-1]) <= np.abs(v[:-2])) & (np.abs(v[1:-1]) <= np.abs(v[2:])) & (np.sign(v[:-2]) == np.sign(v[2:])) ).sum())
                n += cross + tang
            if n == 3:
                tot += a*b
    return tot

def unique():
    tot = 0
    for a in range(1, 7):
        for b in range(1, 7):
            if sum(_cnt(a, b, k) for k in (2, 4, 6)) == 3:
                tot += a*b
    assert tot == standard()
    return [tot]
